'use client';

import type { Variants } from 'motion/react';
import { motion, useAnimation } from 'motion/react';
import type { HTMLAttributes } from 'react';
import { forwardRef } from 'react';
import { useIconAnimation, waveTrain } from '@/lib/use-icon-animation';
import { cn } from '@/lib/utils';

export interface VolumeHighIconHandle {
  startAnimation: () => void;
  stopAnimation: () => void;
}

interface VolumeHighIconProps extends HTMLAttributes<HTMLDivElement> {
  size?: number;
}

// Sound leaves the speaker as a train of waves: each wave rises at the cone
// mouth, travels out through the rest arcs at an even pace, and fades. The
// cone pushes once for each wave while hovered.
const WAVE_CYCLE = 1.2;
const WAVES = [
  'M14 11C14 11.2732 14 11.6211 14 12C14 12.3789 14 12.7267 14 13',
  'M17 9C17.6254 9.81968 18 10.8634 18 12C18 13.1366 17.6254 14.1803 17 15',
  'M20 7C21.2508 8.36613 22 10.1057 22 12C22 13.8943 21.2508 15.6339 20 17',
  'M23 5C24.8762 6.9126 26 9.348 26 12C26 14.652 24.8762 17.0875 23 19',
];

const speakerVariants: Variants = {
  normal: { transform: 'scale(1)' },
  animate: {
    transform: ['scale(1)', 'scale(1.05)', 'scale(0.97)', 'scale(1)'],
    transition: {
      duration: WAVE_CYCLE / 3,
      ease: 'easeInOut',
      times: [0, 0.25, 0.6, 1],
      repeat: Infinity,
    },
  },
};

const waveVariants: Variants = {
  normal: (i: number) => ({
    d: WAVES[i],
    opacity: 1,
    transition: { duration: 0.25, ease: 'easeOut' },
  }),
  animate: (i: number) => waveTrain(WAVES, i, WAVE_CYCLE),
};

const generatedGeometryVariants: Variants = {
  normal: { visibility: 'hidden', transition: { duration: 0.25 } },
  animate: { visibility: 'visible' },
};

const VolumeHighIcon = forwardRef<VolumeHighIconHandle, VolumeHighIconProps>(
  ({ onMouseEnter, onMouseLeave, className, size = 28, ...props }, ref) => {
    const controls = useAnimation();
    const { handleMouseEnter, handleMouseLeave } = useIconAnimation({
      controls,
      loops: true,
      onMouseEnter,
      onMouseLeave,
      ref,
    });

    return (
      <div
        className={cn(className)}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        {...props}
      >
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width={size}
          height={size}
          viewBox="0 0 24 24"
          fill="none"
          overflow="visible"
        >
          <motion.path
            d="M14 14.8135V9.18646C14 6.04126 14 4.46866 13.0747 4.0773C12.1494 3.68593 11.0603 4.79793 8.88232 7.02192C7.75439 8.17365 7.11085 8.42869 5.50604 8.42869C4.10257 8.42869 3.40084 8.42869 2.89675 8.77262C1.85035 9.48655 2.00852 10.882 2.00852 12C2.00852 13.118 1.85035 14.5134 2.89675 15.2274C3.40084 15.5713 4.10257 15.5713 5.50604 15.5713C7.11085 15.5713 7.75439 15.8264 8.88232 16.9781C11.0603 19.2021 12.1494 20.3141 13.0747 19.9227C14 19.5313 14 17.9587 14 14.8135Z"
            stroke="currentColor"
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth="1.5"
            variants={speakerVariants}
            animate={controls}
            initial="normal"
            style={{ transformBox: 'view-box' }}
          />
          <motion.path
            d="M17 9C17.6254 9.81968 18 10.8634 18 12C18 13.1366 17.6254 14.1803 17 15"
            stroke="currentColor"
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth="1.5"
            variants={waveVariants}
            custom={1}
            animate={controls}
            initial="normal"
          />
          <motion.path
            d="M20 7C21.2508 8.36613 22 10.1057 22 12C22 13.8943 21.2508 15.6339 20 17"
            stroke="currentColor"
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth="1.5"
            variants={waveVariants}
            custom={2}
            animate={controls}
            initial="normal"
          />
          <motion.g
            variants={generatedGeometryVariants}
            animate={controls}
            initial="normal"
          >
            <motion.path
              d={WAVES[0]}
              stroke="currentColor"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth="1.5"
              variants={waveVariants}
              custom={0}
              animate={controls}
              initial="normal"
            />
          </motion.g>
        </svg>
      </div>
    );
  }
);

VolumeHighIcon.displayName = 'VolumeHighIcon';

export { VolumeHighIcon };

'use client';

import type { LegacyAnimationControls } from 'motion/react';
import { spring, useReducedMotion } from 'motion/react';
import type {
  ForwardedRef,
  MouseEventHandler,
} from 'react';
import { useCallback, useImperativeHandle, useRef } from 'react';

/**
 * A damped spring as the easing of one keyframe segment: the value overshoots
 * its target and settles on it. Use it for landings so every icon shares the
 * same physical bounce. Higher `bounce` gives more oscillation.
 */
export function springEase(bounce = 0.45, visualDuration = 0.35) {
  const generator = spring({ keyframes: [0, 1], bounce, visualDuration });
  let settle = 0;
  while (!generator.next(settle).done && settle < 5000) settle += 10;
  return (progress: number) =>
    progress >= 1 ? 1 : generator.next(progress * settle).value;
}

/**
 * One wave of a looping wave train, like sound leaving a speaker. The wave
 * fades in at the first pose, moves through each pose at an even pace, fades
 * out at the last, and returns hidden to the first. Give each wave the pose it
 * rests on; waves on neighbouring poses then move as one train. All poses must
 * share the same path commands.
 */
export function waveTrain(poses: string[], rest: number, duration: number) {
  const last = poses.length - 1;
  const steps = [];
  for (let pose = rest; pose <= last; pose++) steps.push(pose);
  for (let pose = 0; rest > 0 && pose <= rest; pose++) steps.push(pose);
  return {
    d: steps.map((pose) => poses[pose]),
    opacity: steps.map((pose) => (pose === 0 || pose === last ? 0 : 1)),
    transition: {
      duration,
      ease: 'linear' as const,
      // The return from the last pose to the first is a hidden jump.
      times: steps.map((_, k) => {
        if (k <= last - rest) return k / last;
        return (k - 1) / last + (k === last - rest + 1 ? 0.001 : 0);
      }),
      repeat: Infinity,
    },
  };
}

export interface AnimatedIconHandle {
  startAnimation: () => void;
  stopAnimation: () => void;
}

interface UseIconAnimationOptions {
  controls: LegacyAnimationControls;
  loops?: boolean;
  onMouseEnter?: MouseEventHandler<HTMLDivElement>;
  onMouseLeave?: MouseEventHandler<HTMLDivElement>;
  ref: ForwardedRef<AnimatedIconHandle>;
}

export function useIconAnimation({
  controls,
  loops = false,
  onMouseEnter,
  onMouseLeave,
  ref,
}: UseIconAnimationOptions) {
  const shouldReduceMotion = useReducedMotion();
  const isControlledRef = useRef(false);
  const isPlayingRef = useRef(false);
  const runRef = useRef(0);

  const startAnimation = useCallback(() => {
    if (shouldReduceMotion || isPlayingRef.current) return;

    isPlayingRef.current = true;
    const run = ++runRef.current;
    controls.set('normal');
    void controls.start('animate').then(() => {
      if (runRef.current === run) isPlayingRef.current = false;
    });
  }, [controls, shouldReduceMotion]);

  const stopAnimation = useCallback(() => {
    if (!loops) return;

    runRef.current++;
    isPlayingRef.current = false;
    void controls.start('normal');
  }, [controls, loops]);

  useImperativeHandle(
    ref,
    () => {
      isControlledRef.current = true;
      return { startAnimation, stopAnimation };
    },
    [startAnimation, stopAnimation]
  );

  const handleMouseEnter = useCallback<MouseEventHandler<HTMLDivElement>>(
    (event) => {
      onMouseEnter?.(event);
      if (!isControlledRef.current) startAnimation();
    },
    [onMouseEnter, startAnimation]
  );

  const handleMouseLeave = useCallback<MouseEventHandler<HTMLDivElement>>(
    (event) => {
      onMouseLeave?.(event);
      if (!isControlledRef.current) stopAnimation();
    },
    [onMouseLeave, stopAnimation]
  );

  return { handleMouseEnter, handleMouseLeave };
}
